-- WorkHub MTY static seed exported from Supabase.
-- Contains only catalog/inventory data: roles, floors, spaces, parking and badges.
-- Demo users/reservations are created by luminaBack-main/seed_production_demo_data.ts.

BEGIN;

-- roles
ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.roles', 'id'), COALESCE((SELECT MAX(id) FROM roles), 1), true);

-- buildings
ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.buildings', 'id'), COALESCE((SELECT MAX(id) FROM buildings), 1), true);

-- floors
ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.floors', 'id'), COALESCE((SELECT MAX(id) FROM floors), 1), true);

-- badges
ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.badges', 'id'), COALESCE((SELECT MAX(id) FROM badges), 1), true);

-- parking_zones
ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.parking_zones', 'id'), COALESCE((SELECT MAX(id) FROM parking_zones), 1), true);

-- parking_spots
ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.parking_spots', 'id'), COALESCE((SELECT MAX(id) FROM parking_spots), 1), true);

-- spaces
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.spaces', 'id'), COALESCE((SELECT MAX(id) FROM spaces), 1), true);

COMMIT;
